const adminStyle=document.createElement('link');adminStyle.rel='stylesheet';adminStyle.href='/admin-v3.css';document.head.append(adminStyle);
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(v),date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('es-AR'):'Por coordinar';
let state={},config={},page=recoveryRoute()||location.hash.slice(1)||'inicio',selectedPost='',adminTab='Solicitudes',workId='',before=new Set(),filter='Todos',serviceFilter='Todos',dirty=false,audioContext,latestNotice,registration,adminRequestFilter='Nuevas',adminQuoteFilter='Pendientes',adminWorkFilter='En curso',adminChatTab='Clientes',adminEmployee='';
const isAdmin=()=>state.user?.role==='admin',btn=(label,action,extra='',cls='primary')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`,options=(items,value)=>items.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const field=(label,name,type='text',value='',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0.01" step="0.01"':''}></label>`;
const heading=(tag,title,body='')=>`<div class="page-heading"><span class="eyebrow">${tag}</span><h1>${title}</h1>${body?`<p>${body}</p>`:''}</div>`,empty=(title,body)=>`<section class="panel empty"><h2>${title}</h2><p>${body}</p></section>`;
const thumb=(urls,meta={})=>`<div class="mini-photos">${(urls||[]).map(url=>`<a href="${esc(url)}" data-sender="${esc(meta.sender||'AMC')}" data-date="${esc(meta.date||'')}" download><img loading="lazy" decoding="async" width="110" height="95" src="${esc(url)}?thumb=1" alt="Foto del proyecto"></a>`).join('')}</div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000);}
let pendingOperations=0,sessionEpoch=0,loggingOut=false;
async function api(url,body,method='POST'){const visible=method!=='GET'&&!url.endsWith('/messages/read');if(visible){pendingOperations++;document.body.dataset.busy='true';toast(url.includes('upload')?'Subiendo archivo…':'Procesando…');}try{const r=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf||''},...(method!=='GET'?{body:JSON.stringify(body||{})}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'No se pudo completar la operación.');return result;}finally{if(visible&&!--pendingOperations)delete document.body.dataset.busy;}}
async function reload(){const epoch=sessionEpoch;const next=await api('/api/state',null,'GET');if(epoch===sessionEpoch)state=next;}
function navigate(p){dirty=false;location.hash=p;if(page===p)render();}
function sound(){if(!state.user?.sound||!audioContext)return;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.frequency.setValueAtTime(740,audioContext.currentTime);osc.frequency.setValueAtTime(990,audioContext.currentTime+.15);gain.gain.setValueAtTime(.22,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.5);osc.start();osc.stop(audioContext.currentTime+.5);}
function auth(register=false){return `<section class="auth panel">${heading('TU CUENTA AMC',register?'Creá tu cuenta':'Ingresá a AMC','Consultá tus pedidos, presupuestos y avances desde cualquier dispositivo.')}<form id="auth" data-register="${register}">${register?field('Nombre completo','name'):''}${field('Correo electrónico','email','email')}<label>Contraseña<input type="password" name="password" minlength="8" maxlength="200" required autocomplete="${register?'new-password':'current-password'}"></label><button class="primary full" type="submit">${register?'Crear cuenta':'Ingresar'}</button></form><div class="auth-links"><a href="#${register?'ingresar':'registro'}">${register?'Ya tengo cuenta':'Crear una cuenta'}</a><a href="#recuperar">Olvidé mi contraseña</a><a href="#inicio">Ver trabajos</a></div>${config.demo?'<div class="notice" style="margin-top:20px">Prueba local: usá los accesos del archivo ACCESO-PRUEBA.md. Los pedidos se comparten entre sesiones de este servidor.</div>':''}</section>`;}
const planning=createPlanning({getState:()=>state,esc,api,upload});
const fieldwork=createFieldwork({getState:()=>state,esc,date,field,heading,empty,api,upload});
const accounts=createAccountClosure({getState:()=>state,esc,date,heading,empty,api,upload});
const team=createTeam({getState:()=>state,esc,money,date,field,heading,empty,api,upload});
