const teamResult=await team.submit(f,data);if(teamResult){if(teamResult!=='cancelled'){await reload();dirty=false;render();toast('Guardado.');}return;}
const featureResult=await features.submit(f,data,submit);if(featureResult==='message-sent'){dirty=false;toast('Mensaje enviado.');return;}if(featureResult){await reload();dirty=false;render();toast('Guardado.');return;}
if(f.id==='client-search'){directory.search(data.search||'');render();return;}if(f.classList.contains('date-reply')){await api('/api/date-proposals/'+f.dataset.id+'/reply',{status:submit.value,message:data.message,revision:f.dataset.revision});await reload();render();toast('Respuesta guardada. AMC recibió el aviso.');return;}if(f.id==='auth'){await api(f.dataset.register==='true'?'/api/register':'/api/login',data);await reload();latestNotice=state.notices?.[0]?.id;dirty=false;navigate(isAdmin()?'inicio':state.user?.role==='employee'?'tareas':'perfil');render();return;}
